        i=g==k; pos=p[i][y[i]==1]; neg=p[i][y[i]==0]
        if len(pos) and len(neg): num+=(pos[:,None]>neg[None,:]).sum()+.5*(pos[:,None]==neg[None,:]).sum(); den+=len(pos)*len(neg)
    return num/den, den
SPL={'val':(tr,ev),'bt13':(tr[em<'2013-01-01'],tr[em>='2013-01-01']),'bt12':(tr[em<'2012-01-01'],tr[em>='2012-07-01']),'rev':(tr[em>='2013-01-01'],tr[em<'2012-01-01'])}
